WITH flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM payments), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT DATE_TRUNC('WEEK', paid_at) AS week_start, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS span_minutes, ROUND(SUM(session_id) / NULLIF(COUNT(CASE WHEN status = 'REFUNDED' THEN 1 END), 0), 2) AS session_id_per_refunded, PERCENTILE_APPROX(session_id, ARRAY(0.25, 0.5, 0.75)) AS session_id_quartiles FROM islands GROUP BY DATE_TRUNC('WEEK', paid_at)
